#include <stdio.h>

/* 挑出最大那只碗，把它的门牌号挂到外面那张牌上 */
void pick_biggest(int *bowls, int n, int **out) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (bowls[i] > bowls[best]) {
            best = i;
        }
    }
    *out = &bowls[best];
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int bowls[100];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    int *p = &bowls[0];
    pick_biggest(bowls, n, &p);

    printf("最大的那只碗里：%d\n", *p);
    return 0;
}
